#!/bin/zsh
# Regenerates Sources/MemeCore/SeedVibesData.swift from seed/vibes.json.
set -euo pipefail
cd "${0:A:h}/.."
python3 -I - <<'EOF'
import json, pathlib
data = json.load(open("seed/vibes.json"))
for key, value in data.items():
    assert set(value) == {"vibe", "tags", "howUsed"}, key
text = json.dumps(data, ensure_ascii=False, sort_keys=True, indent=1)
assert '"""#' not in text
pathlib.Path("Sources/MemeCore/SeedVibesData.swift").write_text(
    "// Generated by scripts/gen-seed.sh from seed/vibes.json. Do not edit by hand.\n"
    "let seedVibesJSON = #\"\"\"\n" + text + "\n\"\"\"#\n"
)
print(f"{len(data)} seed entries")
EOF
